import { test, expect } from '@playwright/test';

test.describe('Dynamic Content Loading - The Internet', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dynamic_loading/1');
  });

  test('should reveal hidden content after asynchronous load', async ({ page }) => {
    // Verify initial state: #finish is hidden
    const finishButton = page.getByRole('button', { name: /start/i });
    await expect(finishButton).toBeVisible();

    const finishElement = page.getByText('Hello World!');
    await expect(finishElement).not.toBeVisible();

    // Click Start button to initiate loading
    await finishButton.click();

    // Wait for loading indicator to appear
    const loadingIndicator = page.getByText('Loading...');
    await expect(loadingIndicator).toBeVisible();

    // Wait for loading to complete
    await page.waitForTimeout(10000);

    // Verify loading indicator is gone
    await expect(loadingIndicator).not.toBeVisible();

    // Verify #finish element is now visible with content
    await expect(finishElement).toBeVisible();
    await expect(finishElement).toContainText('Hello World!');

    // Verify page title is correct
    const pageTitle = page.getByText(/dynamic loading/i);
    await expect(pageTitle).toBeVisible();
  });

  test('should handle failed content load gracefully', async ({ page }) => {
    // Mock failed response
    await page.route('**/api/content', (route) => {
      route.abort('Failed to load content');
    });

    // Click Start button to initiate loading
    const startButton = page.getByRole('button', { name: /start/i });
    await expect(startButton).toBeVisible();
    await startButton.click();

    // Wait for loading indicator to appear
    const loadingIndicator = page.getByText('Loading...');
    await expect(loadingIndicator).toBeVisible();

    // Wait for loading to complete
    await page.waitForTimeout(10000);

    // Verify loading indicator is still visible (failed to load)
    await expect(loadingIndicator).toBeVisible();

    // Verify #finish element is still hidden
    const finishElement = page.getByText('Hello World!');
    await expect(finishElement).not.toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/content could not be loaded/i);
    await expect(errorMessage).toBeVisible();

    // Verify page title is still correct
    const pageTitle = page.getByText(/dynamic loading/i);
    await expect(pageTitle).toBeVisible();
  });
});
